    /**
     * 楕円曲線の x 座標 (X Coordinate)。
     * Base64url エンコードされた値。
     */
    x: string;
    /**
     * 楕円曲線の y 座標 (Y Coordinate)。
     * Base64url エンコードされた値。
     */
    y: string;
    [key: string]: unknown;
